insert into public.reviews (product_id, user_id, rating, title, content, status, created_at) values ('ec7b295f-a553-533a-a92a-33a1a3f0be83', '85aa9d2e-cbad-552a-ad06-bab52e17d01b', 5, 'Even more beautiful in person', 'The embroidery on the neckline is so finely done and the organza dupatta drapes perfectly. Wore it to my sister’s mehndi and was asked about it all evening.', 'approved', now() - interval '30 days');
